	["Draws a white stripe on your own meter bar."] = "Zeichnet einen wei\195\159en Streifen auf Eure eigene Leiste.",
	["Draws cast bars over neighbouring plates."] = "Zeichnet Zauberbalken \195\188ber benachbarte Plaketten.",
	["Draws critical damage in its own colour."] = "Zeichnet kritischen Schaden in einer eigenen Farbe.",
	["Draws debuffs over neighbouring plates."] = "Zeichnet Schw\195\164chungen \195\188ber benachbarte Plaketten.",
	["Draws enemy plates larger while they cast. 1 keeps their size."] = "Zeichnet feindliche Plaketten gr\195\182\195\159er, w\195\164hrend sie zaubern. 1 beh\195\164lt ihre Gr\195\182\195\159e.",
	["Draws every label and unit in your own colour."] = "Zeichnet jede Beschriftung und Einheit in deiner eigenen Farbe.",
	["Draws every unit frame cast bar above other frames so nothing covers it."] = "Zeichnet jede Zauberleiste der Einheitenrahmen \195\188ber anderen Rahmen, damit nichts sie verdeckt.",
	["Draws shields after the health, or back from the bar's end."] = "Zeichnet Schilde nach der Gesundheit oder vom Ende des Balkens zur\195\188ck.",
	["Draws smoked glass behind the buttons."] = "Zeichnet Rauchglas hinter die Kn\195\182pfe.",
	["Draws the chamfered frame around the bar."] = "Zeichnet den abgeschr\195\164gten Rahmen um die Leiste.",
	["Draws the part of a shield larger than the missing health back over the health, from the bar's end."] = "Zeichnet den Teil eines Schilds, der die fehlende Gesundheit \195\188bersteigt, vom Ende des Balkens \195\188ber die Gesundheit.",
	["Draws the strip on smoked glass."] = "Zeichnet den Streifen auf Rauchglas.",
	["Draws the strip's inner edge in the accent colour."] = "Zeichnet die Innenkante des Streifens in der Akzentfarbe.",
	["Draws your target's plate larger. 1 keeps its size."] = "Zeichnet die Plakette deines Ziels gr\195\182\195\159er. 1 beh\195\164lt ihre Gr\195\182\195\159e.",
	["Drink"] = "Getr\195\164nk",
	["Drop a bag here to equip it."] = "Legt hier eine Tasche ab, um sie anzulegen.",
	["Drop a spell below, then click it with the keys and button that should cast it on a member. These are the game's Click Casting bindings."] = "Legt unten einen Zauber ab und klickt ihn dann mit den Tasten und der Maustaste an, die ihn auf ein Mitglied wirken sollen. Das sind die Klickzauber-Belegungen des Spiels.",
	["Drop a spell or macro here"] = "Zauber oder Makro hier ablegen",
	["Drops the word Level and the (Player) tag from the level line."] = "Entfernt das Wort Stufe und die Markierung (Spieler) aus der Stufenzeile.",
	["Druid mana"] = "Druidenmana",
