	["Duration"] = "Dauer",
	["Duration swipe"] = "Ablaufanimation",
	["Each buff keeps its own slot, leaving a gap while it is off you."] = "Jeder Buff beh\195\164lt seinen eigenen Platz und l\195\164sst eine L\195\188cke, solange er nicht auf Euch liegt.",
	["Each character keeps its own pins, starting from the shared ones."] = "Jeder Charakter beh\195\164lt eigene Anheftungen, ausgehend von den gemeinsamen.",
	["Each window's last lines come back after a reload or relog. Turning this off forgets them."] = "Die letzten Zeilen jedes Fensters kehren nach einem Neuladen oder erneuten Einloggen zur\195\188ck. Ausschalten vergisst sie.",
	["Ease mouse wheel zoom and pan. Off restores instant zoom in full steps."] = "Mausrad-Zoom und Verschieben gleiten sanft. Aus: sofortiger Zoom in ganzen Schritten.",
	["Ease the fill to a new value instead of snapping."] = "L\195\164sst die F\195\188llung weich zum neuen Wert gleiten, statt zu springen.",
	["Edges buffs that have a dispel type in its colour, such as magic buffs you can purge."] = "Umrandet St\195\164rkungszauber mit Banntyp in dessen Farbe, etwa Magie, die Ihr reinigen k\195\182nnt.",
	["Edges debuffs in their dispel type's colour."] = "Umrandet Schw\195\164chungszauber in der Farbe ihres Banntyps.",
	["Edges only buffs a spell steal can take."] = "Umrandet nur St\195\164rkungszauber, die ein Zauberraub nehmen kann.",
	["Edit Mode"] = "Bearbeitungsmodus",
	["Edit Mode could not save the layout."] = "Der Bearbeitungsmodus konnte das Layout nicht speichern.",
	["Edit Mode did not take %s. %s"] = "Der Bearbeitungsmodus hat %s nicht \195\188bernommen. %s",
