	["Items in a row, or stacked in a column."] = "Elemente in einer Reihe oder in einer Spalte gestapelt.",
	["Items run together on one line at the right, joined by middle dots. Off, each sits in its own cell."] = "Die Werte laufen rechts auf einer Zeile zusammen, getrennt durch Mittelpunkte. Aus, steht jeder in seiner eigenen Zelle.",
	["Items this search matches fill the section: & both, | either, ! not, type:, ilvl>30, junk, bound."] = "Gegenst\195\164nde, auf die diese Suche passt, f\195\188llen den Abschnitt: & beides, | eines davon, ! nicht, type:, ilvl>30, junk, bound.",
