	["Keep"] = "Behalten",
	["Keep Medallions name face"] = "Medallions-Namensschrift beibehalten",
	["Keep a dimmed icon while the buff is off you. Active buffs come first."] = "Beh\195\164lt ein abgedunkeltes Symbol, solange der St\195\164rkungszauber nicht auf Euch ist. Aktive St\195\164rkungszauber kommen zuerst.",
