	["Keep buffs in place"] = "Buffs an ihrem Platz halten",
	["Keep casting units at full opacity"] = "Zaubernde Einheiten voll deckend halten",
	["Keep chat across sessions"] = "Chat \195\188ber Sitzungen behalten",
	["Keep chat tabs visible, underline their names and leave room above the first message."] = "Chatreiter sichtbar halten, Namen unterstreichen und Platz \195\188ber der ersten Nachricht lassen.",
	["Keep combat text clear"] = "Kampftext freihalten",
	["Keep focus at full opacity"] = "Fokus bei voller Deckkraft halten",
	["Keep gold on hand"] = "Gold bereithalten",
	["Keep hairlines quiet, or use your class colour or a colour you pick."] = "Dezente Konturen, deine Klassenfarbe oder eine frei gew\195\164hlte Farbe verwenden.",
