	["Keep raid tools available"] = "Schlachtzugswerkzeuge verf\195\188gbar halten",
	["Keep round-map labels below the screen edge and clear of the ring. Off uses the old positions."] = "Runde Kartenbeschriftung von Rand und Ring fernhalten. Aus: bisherige Positionen.",
	["Keep rows by the HUD. Turn off for the previous placement. Custom positions are kept."] = "Reihen am HUD. Ausschalten f\195\188r die bisherige Position. Eigene Positionen bleiben erhalten.",
	["Keep settings text readable"] = "Lesbare Optionstexte",
	["Keep text above the reading floor when shrinking this window. Off keeps the previous scaling."] = "H\195\164lt Text beim Verkleinern lesbar. Aus beh\195\164lt die bisherige Skalierung.",
	["Keep the current outline's shadow, or show or hide it explicitly."] = "Den Schatten der aktuellen Kontur beibehalten oder ausdr\195\188cklich ein- oder ausblenden.",
	["Keep the current style, or choose class, reaction, accent or a custom colour."] = "Aktuellen Stil behalten oder Klasse, Reaktion, Akzent oder eine eigene Farbe w\195\164hlen.",
	["Keep the envelope in the column, or in a corner of the map."] = "Den Umschlag in der Spalte lassen oder in eine Ecke der Karte setzen.",
	["Keep the layout and leave Layout Mode."] = "Das Layout behalten und den Layoutmodus verlassen.",
	["Keep the portrait level and leave room for names. Off repeats the level beside the name."] = "Stufe am Portr\195\164t, mehr Platz f\195\188r Namen. Aus zeigt die Stufe nochmals neben dem Namen.",
	["Keep the power bar's room"] = "Platz des Ressourcenbalkens behalten",
	["Keep these cooldowns in colour while cooling and these buffs while off you."] = "H\195\164lt diese Abklingzeiten beim Abklingen und diese St\195\164rkungen ohne Wirkung farbig.",
	["Keep these in colour"] = "Diese farbig lassen",
	["Keep these in full colour while you lack the resource."] = "H\195\164lt diese in voller Farbe, wenn Euch die Ressource fehlt.",
	["Keep titles in player names. Off shows the character name alone."] = "Beh\195\164lt Spielertitel bei. Aus zeigt nur den Charakternamen.",
	["Keep window borders and chat tab underlines on whole pixels. Off restores their original placement."] = "Richtet Fensterr\195\164nder und Chat-Reiter-Unterstreichungen an ganzen Pixeln aus. Aus stellt die urspr\195\188ngliche Platzierung wieder her.",
	["Keep your row visible when it falls outside the meter's visible rows."] = "Deine Zeile sichtbar halten, wenn sie au\195\159erhalb der sichtbaren Zeilen des Z\195\164hlers liegt.",
	["Keeps Blizzard's icon colours, or tints the icons in the accent colour or white."] = "Beh\195\164lt Blizzards Symbolfarben oder t\195\182nt die Symbole in der Akzentfarbe oder in Wei\195\159.",
	["Keeps casting units visible when other plates are dimmed."] = "H\195\164lt zaubernde Einheiten sichtbar, wenn andere Plaketten verblassen.",
	["Keeps danger at the edges and hides it with the UI. Off restores the original red glow."] = "Gefahr am Bildschirmrand, mit der UI verborgen. Aus: urspr\195\188ngliches rotes Leuchten.",
	["Keeps failed casts readable and acknowledges channels. Off restores the original cast effects."] = "Zeigt Zauberfehler l\195\164nger und best\195\164tigt Kan\195\164le. Aus stellt die urspr\195\188nglichen Effekte wieder her.",
	["Keeps other plates quiet while showing the spell your target or focus is casting."] = "Zeigt den Zauber Eures Ziels oder Fokus und h\195\164lt andere Namensplaketten schlicht.",
	["Keeps position and size details visible on every Layout Mode plate."] = "Zeigt Position und Gr\195\182\195\159e auf jedem Verschieber im Layoutmodus an.",
	["Keeps the HUD at its previous size until 120 ms after the last window resize."] = "Beh\195\164lt die bisherige HUD-Gr\195\182\195\159e bis 120 ms nach der letzten \195\132nderung der Fenstergr\195\182\195\159e bei.",
	["Keeps the current style, colours the level by how hard the unit is, or uses your own colour."] = "Beh\195\164lt den aktuellen Stil, f\195\164rbt die Stufe nach Schwierigkeit der Einheit oder nutzt Eure eigene Farbe.",
	["Keeps the game's raid controls available. Off restores the previous hidden raid manager."] = "H\195\164lt die Schlachtzugsverwaltung verf\195\188gbar. Aus stellt die bisher ausgeblendete Verwaltung her.",
	["Keeps the last fight's time on screen after combat."] = "Zeigt nach dem Kampf weiter die Dauer des letzten Kampfes.",
	["Keeps your account's gold for the last seven days you played and shows the change in the tooltip."] = "Merkt sich das Gold deines Accounts f\195\188r die letzten sieben Spieltage und zeigt die \195\132nderung im Tooltip.",
	["Keeps your focus visible when other plates are dimmed."] = "H\195\164lt deinen Fokus sichtbar, wenn andere Plaketten verblassen.",
	["Key ring"] = "Schl\195\188sselbund",
	["Keybind text"] = "Tastenbelegungstext",
