	["KstyleUI applied the %s layout. Type /reload to finish, or /kstyle setup to change it."] = "KstyleUI hat das Layout %s angewendet. Gebt /reload ein, um fertig zu werden, oder /kstyle setup, um es zu \195\164ndern.",
