	["KstyleUI leaves the RestedXP guide where you put it. Turn Story rail back on in the RestedXP skin's settings."] = "KstyleUI l\195\164sst den RestedXP-Guide, wo Ihr ihn hingesetzt habt. Schaltet die Story-Leiste in den Optionen des RestedXP-Skins wieder ein.",
