	["Shift-drag a chat button anywhere, out of combat. Off returns every button to the column."] = "Zieht einen Chatknopf mit Umschalt au\195\159erhalb des Kampfes \195\188berallhin. Aus bringt jeden Knopf in die Spalte zur\195\188ck.",
