	["Show total duration"] = "Gesamtdauer anzeigen",
	["Show what each section's items sell for beside its count."] = "Zeigt neben der Anzahl, was die Gegenst\195\164nde eines Abschnitts beim H\195\164ndler bringen.",
	["Show when solo"] = "Allein zeigen",
