	["Shows 14:32 instead of 2:32 PM."] = "Zeigt 14:32 statt 2:32 PM.",
	["Shows Bind keys buttons and a dash on unbound actions. Off keeps the usual binding display."] = "Zeigt Tasten-belegen-Schaltfl\195\164chen und Striche bei unbelegten Aktionen. Aus beh\195\164lt die \195\188bliche Anzeige.",
	["Shows Blizzard's art behind the Legacy pages instead of plain glass."] = "Zeigt Blizzards Bild hinter den Seiten von Klassisch statt schlichtem Glas.",
	["Shows KstyleUI's bag bar in place of Blizzard's. Off, Blizzard's returns."] = "Zeigt KstyleUIs Taschenleiste anstelle von Blizzards. Aus kehrt Blizzards zur\195\188ck.",
