	["Shows T, H or D in the role's colour instead of the role icon."] = "Zeigt T, H oder D in der Farbe der Rolle statt des Rollensymbols.",
	["Shows Zz while you rest in an inn or a city."] = "Zeigt Zz, solange Ihr in einem Gasthaus oder einer Stadt ruht.",
	["Shows a LibDataBroker plugin from another addon."] = "Zeigt ein LibDataBroker-Plugin eines anderen Addons.",
