	["Shows a bar for your ranged attacks."] = "Zeigt eine Leiste f\195\188r Eure Distanzangriffe.",
	["Shows a button on the damage meter's title that clears every fight, after combat."] = "Zeigt im Titel der Schadensanzeige einen Knopf, der nach dem Kampf alle K\195\164mpfe l\195\182scht.",
	["Shows a card of the spells you cast last, like the damage meter. Move it in Layout Mode."] = "Zeigt eine Karte Eurer letzten Zauber wie die Schadensanzeige. Im Layoutmodus verschieben.",
	["Shows a crown when the unit leads the group."] = "Zeigt eine Krone, wenn die Einheit die Gruppe anf\195\188hrt.",
	["Shows a debuff's tooltip when you point at its icon."] = "Zeigt den Tooltip eines Schw\195\164chungszaubers, wenn Ihr auf sein Symbol zeigt.",
	["Shows a debuff's tooltip while you hover it. The plate behind the icon does not take the mouse."] = "Zeigt den Tooltip einer Schw\195\164chung beim \195\156berfahren. Die Plakette dahinter erh\195\164lt die Maus nicht.",
	["Shows a faction badge after the names of units flagged for PvP."] = "Zeigt ein Fraktionsabzeichen hinter den Namen von Einheiten mit PvP-Markierung.",
	["Shows a few debuffs on each frame."] = "Zeigt auf jedem Rahmen einige Schw\195\164chungszauber.",
	["Shows a heal's tooltip when you point at its icon."] = "Zeigt den Tooltip einer Heilung, wenn Ihr auf ihr Symbol zeigt.",
	["Shows a player's buffs as icons beside the tooltip whenever the game shares them."] = "Zeigt die St\195\164rkungszauber eines Spielers als Symbole neben dem Tooltip, wenn das Spiel sie preisgibt.",
	["Shows a player's guild in angle brackets, green for your own guild."] = "Zeigt die Gilde eines Spielers in spitzen Klammern, gr\195\188n f\195\188r Eure eigene Gilde.",
	["Shows a portrait beside the bars."] = "Zeigt ein Portr\195\164t neben den Leisten.",
	["Shows a strip of the spells you cast last. Move it in Layout Mode."] = "Zeigt eine Leiste Eurer letzten Zauber. Im Layoutmodus verschieben.",
	["Shows a thin mana, rage or energy bar under the health bar."] = "Zeigt eine d\195\188nne Mana-, Wut- oder Energieleiste unter dem Gesundheitsbalken.",
	["Shows absorb shields when incoming heals are enabled."] = "Zeigt Absorptionsschilde, wenn eingehende Heilung aktiviert ist.",
	["Shows all your profiles, character and specialization choices, account preferences and profile hotkeys as one string to copy."] = "Zeigt alle Profile, Charakter- und Spezialisierungszuordnungen, Accounteinstellungen und Profilk\195\188rzel als eine Zeichenfolge zum Kopieren.",
	["Shows an envelope while you have unread mail."] = "Zeigt einen Umschlag, solange Ihr ungelesene Post habt.",
	["Shows an eye while you are queued, in place of Blizzard's queue eye."] = "Zeigt ein Auge, solange Ihr in einer Warteschlange seid, anstelle von Blizzards Warteschlangenauge.",
	["Shows an item, spell or quest tooltip while the pointer is over its link in chat."] = "Zeigt den Tooltip eines Gegenstands, Zaubers oder einer Quest, solange der Zeiger auf dem Link ist.",
	["Shows another damage meter with its own Show and Fight. Move it in Layout Mode."] = "Zeigt eine weitere Schadensanzeige mit eigenem Anzeigen und Kampf. Im Layoutmodus verschieben.",
	["Shows combo points and the druid's mana under the player frame."] = "Zeigt Combopunkte und das Mana des Druiden unter dem Spielerrahmen.",
	["Shows crossed swords on members who are in combat."] = "Zeigt gekreuzte Schwerter bei Mitgliedern, die im Kampf sind.",
