	["Shows on the backpack how many slots are free in all your bags."] = "Zeigt auf dem Rucksack, wie viele Pl\195\164tze in allen Taschen frei sind.",
	["Shows online Warcraft and Battle.net friends."] = "Zeigt Freunde aus Warcraft und Battle.net online.",
	["Shows only auras you cast."] = "Zeigt nur Auren, die Ihr gewirkt habt.",
	["Shows only debuffs you can dispel; for buffs, only ones you can apply."] = "Zeigt nur bannbare Schw\195\164chungen; bei St\195\164rkungen nur solche, die du wirken kannst.",
