	["Shows shields, such as Power Word: Shield, after the health."] = "Zeigt Schilde wie Machtwort: Schild nach der Gesundheit.",
	["Shows slots with no action as empty tiles."] = "Zeigt Pl\195\164tze ohne Aktion als leere Kacheln.",
	["Shows tab names in capitals or as you typed them."] = "Zeigt Reiternamen in Gro\195\159buchstaben oder so, wie Ihr sie eingegeben habt.",
	["Shows temporary weapon enchantments, such as poisons and oils, before your buffs."] = "Zeigt vor\195\188bergehende Waffenverzauberungen wie Gifte und \195\150le vor Euren St\195\164rkungszaubern.",
	["Shows tenths of a second."] = "Zeigt Zehntelsekunden.",
