	["Thargor, the route guide:"] = "Thargor, der Routenguide:",
	["That did not work"] = "Das hat nicht geklappt",
	["The DPS layout with taller party rows and raid rows wide enough for three of your heals, dispellable debuffs first."] = "Die DPS-Anordnung mit h\195\182heren Gruppenzeilen und Schlachtzugszeilen, breit genug f\195\188r drei Eurer Heilungen; bannbare Schw\195\164chungen zuerst.",
	["The DPS layout with the threat meter on the right, under the quest card, where it reads who holds aggro without covering the enemies' nameplates."] = "Das Schadenslayout mit der Bedrohungsanzeige rechts unter der Questkarte, wo sie zeigt, wer die Aggro hat, ohne die Namensplaketten der Gegner zu verdecken.",
	["The Layout Mode toolbar rests at 25 percent until pointed at; hold Shift to hide it."] = "Die Leiste des Layoutmodus ruht bei 25 Prozent, bis Ihr darauf zeigt; Umschalt verbirgt sie.",
	["The LibDataBroker plugin's name, as its addon registers it."] = "Der Name des LibDataBroker-Plugins, wie sein Addon ihn registriert.",
	["The Show or hide meters key in Key Bindings also hides spell history."] = "Die Taste \226\128\158Anzeigen ein- oder ausblenden\226\128\156 in den Tastaturbelegungen blendet auch den Zauberverlauf aus.",
	["The Show or hide meters key in Key Bindings also hides the combat timer."] = "Die Taste \226\128\158Anzeigen ein- oder ausblenden\226\128\156 in den Tastaturbelegungen blendet auch den Kampftimer aus.",
	["The accent KstyleUI uses when the accent colour is set to custom."] = "Der Akzent, den KstyleUI nutzt, wenn die Akzentfarbe auf Benutzerdefiniert steht.",
	["The accent colour the meters use when the accent is custom."] = "Die Akzentfarbe der Anzeigen, wenn der Akzent benutzerdefiniert ist.",
	["The accent colour when it does not follow your class."] = "Die Akzentfarbe, wenn sie nicht Eurer Klasse folgt.",
	["The accent colour when the accent is custom."] = "Die Akzentfarbe, wenn der Akzent benutzerdefiniert ist.",
	["The accent colour when the accent is set to custom."] = "Die Akzentfarbe, wenn der Akzent auf Benutzerdefiniert steht.",
	["The accent used when Accent is set to custom."] = "Der Akzent, wenn Akzent auf Benutzerdefiniert steht.",
	["The accent when Accent colour is set to custom."] = "Der Akzent, wenn Akzentfarbe auf Benutzerdefiniert steht.",
	["The attached element"] = "Das angeheftete Element",
	["The bank change takes effect after you type /reload."] = "Die \195\132nderung der Bank wirkt, nachdem Ihr /reload eingegeben habt.",
	["The bank window changes after a reload."] = "Das Bankfenster \195\164ndert sich nach einem Neuladen.",
	["The bar colour of casters."] = "Die Leistenfarbe von Zauberwirkern.",
	["The bar colour of elites."] = "Die Leistenfarbe von Elite.",
	["The bar colour of enemies while they cast."] = "Die Leistenfarbe von Feinden, w\195\164hrend sie zaubern.",
	["The bar colour of quest mobs."] = "Die Leistenfarbe von Questgegnern.",
	["The bar colour of rares."] = "Die Leistenfarbe seltener Gegner.",
	["The bar colour of this unit type."] = "Die Balkenfarbe dieser Einheitenart.",
	["The bar colour when Bar colour is set to custom."] = "Die Leistenfarbe, wenn Leistenfarbe auf Benutzerdefiniert steht.",
	["The bar colour when it is custom."] = "Die Leistenfarbe, wenn sie eigen ist.",
	["The bar's colour as health runs out."] = "Die Farbe des Balkens, wenn die Gesundheit zur Neige geht.",
	["The bar's colour at full health; it blends toward the half health colour as health falls."] = "Die Farbe des Balkens bei voller Gesundheit; sie geht mit sinkender Gesundheit in die Farbe f\195\188r halbe Gesundheit \195\188ber.",
	["The bar's colour at half health."] = "Die Farbe des Balkens bei halber Gesundheit.",
	["The bar's colour when its colour source is custom."] = "Die Farbe der Leiste, wenn ihre Farbquelle benutzerdefiniert ist.",
	["The bar's colour while a member is dead or a ghost."] = "Die Farbe des Balkens, solange ein Mitglied tot oder ein Geist ist.",
	["The bar's colour while a member is offline."] = "Die Farbe des Balkens, solange ein Mitglied offline ist.",
	["The bright blocks change with the role. The outlined space on the right rail, under the map, is the Story rail: Apply places the quest tracker there through Edit Mode, and Window skins put the RestedXP guide above it."] = "Die hellen Bl\195\182cke \195\164ndern sich mit der Rolle. Der umrandete Bereich auf der rechten Leiste unter der Karte ist die Story-Leiste: Anwenden setzt die Questverfolgung \195\188ber den Bearbeitungsmodus dorthin, und die Fenster-Skins setzen den RestedXP-Leitfaden dar\195\188ber.",
	["The calendar opens from here out of combat."] = "Der Kalender \195\182ffnet sich hier au\195\159erhalb des Kampfes.",
	["The card starts below the tab row, so the tabs sit above it."] = "Die Karte beginnt unter der Reiterzeile, sodass die Reiter dar\195\188ber sitzen.",
	["The coins the gold list shows for each character."] = "Die M\195\188nzen, die die Goldliste je Charakter zeigt.",
	["The colour of casts nothing can interrupt."] = "Die Farbe von Zaubern, die nichts unterbrechen kann.",
	["The colour of casts you can interrupt."] = "Die Farbe unterbrechbarer Zauber.",
	["The colour of casts you could interrupt, while your interrupt is on cooldown."] = "Die Farbe von Zaubern, die Ihr unterbrechen k\195\182nntet, solange Eure Unterbrechung abklingt.",
	["The colour of critical damage."] = "Die Farbe kritischen Schadens.",
	["The colour of damage when it does not follow the school, or the school is hidden."] = "Die Farbe von Schaden, wenn sie nicht der Schule folgt oder die Schule verborgen ist.",
	["The colour of enter and leave combat messages."] = "Die Farbe der Meldungen bei Kampfbeginn und -ende.",
	["The colour of every value when the value colour is custom."] = "Die Farbe jedes Werts, wenn die Wertfarbe eigen ist.",
	["The colour of glows and hairlines when the accent is custom."] = "Die Farbe von Leuchten und Haarlinien, wenn der Akzent benutzerdefiniert ist.",
	["The colour of heal absorbs on the health bar."] = "Die Farbe der Heilungsabsorption auf dem Gesundheitsbalken.",
	["The colour of healing numbers."] = "Die Farbe der Heilungszahlen.",
	["The colour of important casts and their glow."] = "Die Farbe wichtiger Zauber und ihres Leuchtens.",
	["The colour of incoming heals on the health bar."] = "Die Farbe eintreffender Heilung auf dem Gesundheitsbalken.",
	["The colour of power gains."] = "Die Farbe der Ressourcengewinne.",
	["The colour of selected tabs, headers and hairlines in skinned windows."] = "Die Farbe gew\195\164hlter Reiter, \195\156berschriften und Haarlinien in gestalteten Fenstern.",
	["The colour of shields on the health bar."] = "Die Farbe der Schilde auf dem Gesundheitsbalken.",
	["The colour of the You target and spell icon rims: your class colour or one you pick."] = "Die Farbe des Ziels Ihr und der R\195\164nder der Zaubersymbole: Eure Klassenfarbe oder eine Eurer Wahl.",
	["The colour of the alert as you enter combat."] = "Die Farbe des Hinweises beim Betreten des Kampfes.",
	["The colour of the alert as you leave combat."] = "Die Farbe des Hinweises beim Verlassen des Kampfes.",
	["The colour of the button edges and proc glows."] = "Die Farbe der Knopfkanten und Proc-Leuchten.",
	["The colour of the combat timer."] = "Die Farbe des Kampftimers.",
	["The colour of the cursor ring."] = "Die Farbe des Zeigerrings.",
	["The colour of the important cast outline."] = "Die Farbe des Umrisses bei wichtigen Zaubern.",
	["The colour of the labels and units."] = "Die Farbe der Beschriftungen und Einheiten.",
	["The colour of the line around each buff."] = "Die Farbe der Linie um jeden St\195\164rkungszauber.",
	["The colour of the meters' title marks: the class colour or one you pick."] = "Die Farbe der Titelmarken der Anzeigen: die Klassenfarbe oder eine Eurer Wahl.",
	["The colour of the portrait frames, and of the badges on round portraits."] = "Die Farbe der Portr\195\164trahmen und der Abzeichen auf runden Portr\195\164ts.",
	["The colour of the rested overlay."] = "Die Farbe der Erholungs\195\188berlagerung.",
	["The colour of the strip's accent touches: your class colour or your own."] = "Die Farbe der Akzente des Streifens: Eure Klassenfarbe oder Eure eigene.",
	["The colour of the target highlight."] = "Die Farbe der Zielhervorhebung.",
	["The colour of the time in front of each line."] = "Die Farbe der Uhrzeit vor jeder Zeile.",
	["The colour of the unspent talents alert."] = "Die Farbe des Hinweises f\195\188r unverteilte Talente.",
	["The colour of the window's hairlines and the new item glow."] = "Die Farbe der Haarlinien des Fensters und des Leuchtens neuer Gegenst\195\164nde.",
	["The colour of this text."] = "Die Farbe dieses Texts.",
	["The colour of words such as Dodge and Absorb."] = "Die Farbe von W\195\182rtern wie Ausweichen und Absorbieren.",
	["The colour that brightens your target's health bar."] = "Die Farbe, die den Gesundheitsbalken deines Ziels aufhellt.",
	["The colour that marks your target and the frame under the mouse."] = "Die Farbe, die Euer Ziel und den Rahmen unter der Maus markiert.",
	["The colour the chat uses when the accent is set to a custom colour."] = "Die Farbe, die der Chat nutzt, wenn der Akzent auf eine eigene Farbe gesetzt ist.",
	["The combat choice follows the mouse outside combat and uses the Layout Mode anchor in combat."] = "Die Kampfoption folgt au\195\159erhalb des Kampfes der Maus und nutzt im Kampf den Layoutmodus-Anker.",
	["The consumables bar starts at half size with a backdrop."] = "Die Verbrauchsgegenstandsleiste startet in halber Gr\195\182\195\159e mit Hintergrund.",
	["The consumables bar stays where you move it in Layout Mode."] = "Die Verbrauchsgegenstandsleiste bleibt dort, wohin Ihr sie im Layoutmodus verschiebt.",
	["The countdown colour when it is custom."] = "Die Countdown-Farbe, wenn sie eigen ist.",
	["The crystal disc behind each button. Off shows the bare symbols."] = "Die Kristallscheibe hinter jeder Taste. Aus zeigt nur die Symbole.",
	["The current fight, the one before it, or every fight. Right-click the meter to switch."] = "Der aktuelle Kampf, der davor, oder alle K\195\164mpfe. Rechtsklickt auf die Anzeige, um zu wechseln.",
	["The direction the buttons grow from the first one."] = "Die Richtung, in die die Kn\195\182pfe vom ersten aus wachsen.",
	["The distance between grid lines, in interface units."] = "Der Abstand zwischen Rasterlinien, in Oberfl\195\164cheneinheiten.",
	["The edge colour of your focus's plate."] = "Die Kantenfarbe der Plakette Eures Fokus.",
	["The eight you reach for"] = "Die acht, nach denen Ihr greift!",
	["The element's height in interface units."] = "Die H\195\182he des Elements in Oberfl\195\164cheneinheiten.",
	["The element's width in interface units."] = "Die Breite des Elements in Oberfl\195\164cheneinheiten.",
	["The energy bar's width against the row of points."] = "Die Breite der Energieleiste im Verh\195\164ltnis zur Punktreihe.",
	["The fewest players a raid needs for the compact frames."] = "Die wenigsten Spieler, die ein Schlachtzug f\195\188r die kompakten Rahmen braucht.",
	["The fill colour for channels. Uninterruptible colour still takes priority."] = "Die F\195\188llfarbe f\195\188r Kanalisierungen. Die Farbe f\195\188r nicht unterbrechbare Zauber hat weiterhin Vorrang.",
	["The fill of reputation, currency and quest progress bars."] = "Die F\195\188llung von Ruf-, W\195\164hrungs- und Questfortschrittsleisten.",
	["The fill texture of the health bar."] = "Die F\195\188lltextur des Gesundheitsbalkens.",
	["The first-run setup is not available yet."] = "Die Ersteinrichtung ist noch nicht verf\195\188gbar.",
	["The font of charge and stack counts."] = "Die Schrift der Aufladungs- und Stapelanzahl.",
	["The font of chat messages and the edit box. Tabs use the caps face."] = "Die Schrift der Chatnachrichten und des Eingabefelds. Reiter nutzen die Titelschrift.",
	["The font of plate values, debuff timers and optional cast text. Names use the kit's Cinzel heading."] = "Die Schrift f\195\188r Namensplakettenwerte, Schw\195\164chungszauber-Timer und optionalen Zaubertext. Namen verwenden die Cinzel-\195\156berschrift des Kits.",
	["The font of skinned window titles, headers and lists."] = "Die Schrift der Titel, \195\156berschriften und Listen gestalteter Fenster.",
	["The font of stack counts and item levels."] = "Die Schrift der Stapelanzahl und Gegenstandsstufen.",
	["The font of the bar's text."] = "Die Schrift des Leistentexts.",
	["The font of the countdown numbers."] = "Die Schrift der Countdown-Zahlen.",
	["The font of the health text."] = "Die Schrift des Gesundheitstexts.",
	["The font of the names on buff bars."] = "Die Schrift der Namen auf St\195\164rkungsleisten.",
	["The font of the names."] = "Die Schrift der Namen.",
	["The font of the strip's text."] = "Die Schrift des Streifentexts.",
	["The font of the tab names. The default is the caps face."] = "Die Schrift der Reiternamen. Standard ist die Kapit\195\164lchen-Schrift.",
	["The font of this text on every bar."] = "Die Schrift dieses Texts auf jeder Leiste.",
	["The game refused the binding."] = "Das Spiel hat die Belegung abgelehnt.",
	["The game's addon profiler is off, so there is no CPU readout."] = "Der Addon-Profiler des Spiels ist aus, daher gibt es keine CPU-Anzeige.",
	["The game's numbers over targets show only your own hits. Hide turns them off."] = "Die Zahlen des Spiels \195\188ber Zielen zeigen nur Eure eigenen Treffer. Ausblenden schaltet sie ab.",
	["The game's order"] = "Reihenfolge des Spiels",
	["The game's own damage numbers change font after you log out to the character screen and back in; /reload is not enough."] = "Die Schadenszahlen des Spiels wechseln die Schrift, nachdem Ihr Euch zur Charakterauswahl aus- und wieder eingeloggt habt; /reload reicht nicht aus.",
	["The game's own plate size, which sets where you can click and how plates stack."] = "Die Plakettengr\195\182\195\159e des Spiels, die festlegt, wo Ihr klicken k\195\182nnt und wie Plaketten stapeln.",
	["The game's own size"] = "Gr\195\182\195\159e des Spiels",
	["The game's setting"] = "Einstellung des Spiels",
	["The gap between addon buttons in the drawer."] = "Der Abstand zwischen Addon-Kn\195\182pfen in der Schublade.",
	["The gap between aura icons in units."] = "Der Abstand zwischen Aura-Symbolen in Einheiten.",
	["The gap between bars."] = "Der Abstand zwischen Leisten.",
	["The gap between boss frames in units. The frames share the element's height."] = "Der Abstand zwischen Bossrahmen in Einheiten. Die Rahmen teilen sich die H\195\182he des Elements.",
	["The gap between buttons."] = "Der Abstand zwischen Kn\195\182pfen.",
	["The gap between buttons. -1 keeps the HUD style's default spacing."] = "Der Abstand zwischen Tasten. -1 beh\195\164lt den Standardabstand des HUD-Stils bei.",
	["The gap between combo point pips in units."] = "Der Abstand zwischen Combopunkten in Einheiten.",
	["The gap between debuff icons."] = "Der Abstand zwischen Schw\195\164chungssymbolen.",
	["The gap between frames."] = "Der Abstand zwischen Rahmen.",
	["The gap between groups or columns."] = "Der Abstand zwischen Gruppen oder Spalten.",
	["The gap between icons in a row."] = "Der Abstand zwischen Symbolen in einer Reihe.",
	["The gap between icons."] = "Der Abstand zwischen Symbolen.",
	["The gap between item slots."] = "Der Abstand zwischen Gegenstandspl\195\164tzen.",
	["The gap between rows."] = "Der Abstand zwischen Reihen.",
	["The gap between spell icons."] = "Der Abstand zwischen den Zaubersymbolen.",
	["The gap between stacked chat buttons, in units."] = "Der Abstand zwischen gestapelten Chatkn\195\182pfen, in Einheiten.",
	["The gap between the buttons in the column."] = "Der Abstand zwischen den Kn\195\182pfen in der Spalte.",
	["The gap between the card and the chat buttons beside it, in units."] = "Der Abstand zwischen der Karte und den Chatkn\195\182pfen daneben, in Einheiten.",
	["The gap between the main-hand, off-hand and ranged bars."] = "Der Abstand zwischen den Leisten f\195\188r Waffenhand, Schildhand und Distanz.",
	["The gap between the points."] = "Der Abstand zwischen den Punkten.",
	["The gap from the attached element, in interface units."] = "Der Abstand zum angehefteten Element in Oberfl\195\164cheneinheiten.",
	["The glow colour when it is custom."] = "Die Leuchtfarbe, wenn sie eigen ist.",
	["The gold each character keeps when the bank opens. Empty moves nothing."] = "Das Gold, das jeder Charakter beim \195\150ffnen der Bank beh\195\164lt. Leer bewegt nichts.",
	["The ground may block this."] = "Das Gel\195\164nde kann den Weg versperren.",
	["The hairline colour when it does not follow your class."] = "Die Haarlinienfarbe, wenn sie nicht Eurer Klasse folgt.",
	["The health bar colour when Bar colour is set to custom."] = "Die Farbe des Gesundheitsbalkens, wenn Leistenfarbe auf Benutzerdefiniert steht.",
	["The health bar runs the frame's full height and the power bar lies over its foot."] = "Der Gesundheitsbalken nutzt die volle Rahmenh\195\182he, und der Ressourcenbalken liegt \195\188ber seinem Fu\195\159.",
	["The health percent the line marks."] = "Der Gesundheitswert, den die Linie markiert.",
	["The height of each bar, in interface units."] = "Die H\195\182he jeder Leiste in Oberfl\195\164cheneinheiten.",
	["The height of each button. Layout Mode moves and scales the bar."] = "Die H\195\182he jedes Knopfs. Der Layoutmodus verschiebt und skaliert die Leiste.",
	["The height of each row in the list."] = "Die H\195\182he jeder Zeile der Liste.",
	["The height of the energy bar, in interface units."] = "Die H\195\182he der Energieleiste in Interface-Einheiten.",
	["The height of the power bar in interface units."] = "Die H\195\182he der Ressourcenleiste in Oberfl\195\164cheneinheiten.",
	["The height of the tab row above the messages, in units."] = "Die H\195\182he der Reiterzeile \195\188ber den Nachrichten, in Einheiten.",
	["The height of the tile drawn behind the text you type, in units."] = "Die H\195\182he der Kachel hinter dem Text, den du tippst, in Einheiten.",
	["The height of the top data bar."] = "Die H\195\182he der oberen Datenleiste.",
	["The highlight colour when it uses a custom colour."] = "Die Hervorhebungsfarbe, wenn sie eine eigene Farbe nutzt.",
	["The highlight's outline: two lines, one, or none for the tint alone."] = "Der Umriss der Hervorhebung: zwei Linien, eine oder keine f\195\188r die T\195\182nung allein.",
	["The horizontal line's thickness in pixels; zero follows the style."] = "St\195\164rke der horizontalen Linie in Pixeln; null folgt dem Stil.",
	["The indicator's icon size."] = "Die Symbolgr\195\182\195\159e des Anzeigers.",
	["The instances that start the combat log."] = "Die Instanzen, die das Kampflog starten.",
	["The large unit name on column unit frames."] = "Der gro\195\159e Einheitenname auf spaltenf\195\182rmigen Einheitenrahmen.",
	["The length of the horizontal line."] = "Die L\195\164nge der horizontalen Linie.",
	["The length of the vertical line."] = "Die L\195\164nge der vertikalen Linie.",
	["The lowest item quality that colours a border."] = "Die niedrigste Gegenstandsqualit\195\164t, die einen Rahmen f\195\164rbt.",
	["The lowest item quality that colours a slot border."] = "Die niedrigste Gegenstandsqualit\195\164t, die einen Platzrahmen f\195\164rbt.",
	["The lowest quality whose border is coloured."] = "Die niedrigste Qualit\195\164t, deren Rahmen gef\195\164rbt wird.",
	["The maximum number of spells in a row's hover breakdown."] = "Die H\195\182chstzahl der Zauber in der Aufschl\195\188sselung beim Dar\195\188berfahren \195\188ber eine Zeile.",
	["The meter can report after combat."] = "Die Anzeige kann nach dem Kampf berichten.",
	["The meter to show while healing. This overrides the manual show switches."] = "Die Anzeige beim Heilen. Ersetzt die manuellen Anzeigeschalter.",
	["The meter to show while tanking. This overrides the manual show switches."] = "Die Anzeige beim Tanken. Ersetzt die manuellen Anzeigeschalter.",
	["The most debuffs each frame shows."] = "Die meisten Schw\195\164chungszauber, die jeder Rahmen zeigt.",
	["The most numbers one place shows at a time; the oldest makes way."] = "Die meisten Zahlen, die eine Stelle gleichzeitig zeigt; die \195\164lteste macht Platz.",
	["The most of your heals over time and shields each frame shows."] = "Die meisten Eurer Heilungen \195\188ber Zeit und Schilde, die jeder Rahmen zeigt.",
	["The most players a raid may have and still get the larger frames."] = "Die meisten Spieler, die ein Schlachtzug haben darf, um noch die gr\195\182\195\159eren Rahmen zu erhalten.",
	["The name only"] = "Nur der Name",
	["The names' colour when they use a custom colour."] = "Die Farbe der Namen, wenn sie eine eigene Farbe nutzen.",
