	["The size of those icons; 0 sizes them to the bar."] = "Die Gr\195\182\195\159e dieser Symbole; 0 richtet sie nach dem Balken.",
	["The size the game stacks and clicks plates by. KstyleUI's plate keeps stacked plates apart."] = "Die Gr\195\182\195\159e, nach der das Spiel Plaketten stapelt und anklickbar macht. KstyleUIs Plakette h\195\164lt gestapelte Plaketten auseinander.",
	["The slab fixes button order. Turn it off above to reverse these bars."] = "Die Leistenplatte legt die Tastenreihenfolge fest. Schalte sie oben aus, um diese Leisten umzukehren.",
	["The slab joins bars 1 and 2 into one row each, with fixed spacing and backing. Turn off Use the Medallions slab above to unlock rows, spacing, growth and split. Button size scales both sides."] = "Die Platte verbindet Leisten 1 und 2 mit je einer Reihe, festem Abstand und Hintergrund. Deaktiviert oben die Medaillonplatte, um Reihen, Abstand, Wachstum und Teilung frei einzustellen. Die Knopfgr\195\182\195\159e skaliert beide Seiten.",
	["The sound that plays with a group death alert."] = "Der Klang zu einem Gruppentod-Hinweis.",
	["The space after each tab name, in units."] = "Der Abstand nach jedem Reiternamen, in Einheiten.",
	["The spell the recharging colour watches. Blank finds your class's interrupt."] = "Der Zauber, den die Aufladefarbe beobachtet. Leer findet die Unterbrechung Eurer Klasse.",
	["The spells show after combat."] = "Die Zauber erscheinen nach dem Kampf.",
	["The swipe tint when it is custom."] = "Die Ablauff\195\164rbung, wenn sie eigen ist.",
	["The system buttons under the readout. Off, the card is one line; keybinds and Escape still work."] = "Die Systemkn\195\182pfe unter der Anzeige. Aus: Die Karte ist eine Zeile; Tastenbelegungen und Esc wirken weiter.",
	["The tallest the bag and bank windows grow, as a percentage of the screen's height."] = "Die gr\195\182\195\159te H\195\182he von Taschen- und Bankfenster in Prozent der Bildschirmh\195\182he.",
	["The target highlight follows the accent or uses your own colour."] = "Die Zielhervorhebung folgt dem Akzent oder nutzt Eure eigene Farbe.",
	["The target ring's thickness: two lines or one."] = "Die Dicke des Zielrings: zwei Linien oder eine.",
	["The text colour when its colour mode is custom."] = "Die Textfarbe bei eigener Farbauswahl.",
	["The text size in KstyleUI units; Appearance's text size scales it too."] = "Die Textgr\195\182\195\159e in KstyleUI-Einheiten; die Textgr\195\182\195\159e unter Darstellung skaliert sie ebenfalls.",
	["The text size of numbers on party and raid frames."] = "Die Textgr\195\182\195\159e der Zahlen auf Gruppen- und Schlachtzugsrahmen.",
	["The text size of the numbers."] = "Die Textgr\195\182\195\159e der Zahlen.",
