	["The text size of the timers."] = "Die Textgr\195\182\195\159e der Timer.",
	["The texture of the health and power bars."] = "Die Textur der Lebens- und Ressourcenleisten.",
	["The texture the bar is filled with."] = "Die Textur, mit der die Leiste gef\195\188llt wird.",
	["The threat percentage that turns the meter red and makes it pulse."] = "Der Bedrohungsprozentsatz, ab dem die Anzeige rot wird und pulsiert.",
	["The threat percentage that turns the meter yellow."] = "Der Bedrohungsprozentsatz, ab dem die Anzeige gelb wird.",
	["The tint of a spell whose target is out of range."] = "Die F\195\164rbung eines Zaubers, dessen Ziel au\195\159er Reichweite ist.",
	["The tooltip accent when Accent colour is set to custom."] = "Der Tooltip-Akzent, wenn Akzentfarbe auf Benutzerdefiniert steht.",
	["The travel menu will be ready after combat."] = "Das Reisemen\195\188 ist nach dem Kampf bereit.",
	["The typeface for these lines while Use KstyleUI's font is off."] = "Die Schrift f\195\188r diese Zeilen, solange KstyleUI-Schrift nutzen aus ist.",
	["The typeface of the %s."] = "Die Schrift f\195\188r %s.",
	["The typeface of the numbers."] = "Die Schrift der Zahlen.",
	["The typeface of the stack counts on the icons."] = "Die Schrift der Stapelanzahl auf den Symbolen.",
	["The typeface of the text. The interface font follows the Appearance page."] = "Die Schrift des Texts. Die Oberfl\195\164chenschrift folgt der Seite Darstellung.",
	["The typeface of the timers."] = "Die Schrift der Timer.",
	["The value alone, or with your level or the faction."] = "Nur der Wert oder mit deiner Stufe bzw. der Fraktion.",
	["The vertical line's thickness in pixels; zero follows the style."] = "St\195\164rke der vertikalen Linie in Pixeln; null folgt dem Stil.",
	["The way Sort packs items across your bags."] = "Wie Sortieren Gegenst\195\164nde \195\188ber Eure Taschen verteilt.",
	["The way the grid fills from its first slot."] = "Wie sich das Raster von seinem ersten Platz aus f\195\188llt.",
	["The whole chat fades after a quiet spell. Hovering, typing or new player chat brings it back."] = "Der ganze Chat blendet nach einer Weile Ruhe aus. Zeiger, Tippen oder neuer Spielerchat holen ihn zur\195\188ck.",
	["The width and height of each button in the column."] = "Breite und H\195\182he jedes Knopfs in der Spalte.",
	["The width and height of each icon."] = "Breite und H\195\182he jedes Symbols.",
	["The width of each bar, icon included."] = "Die Breite jeder Leiste, samt Symbol.",
	["The width of the health bar, in interface units."] = "Die Breite des Lebensbalkens in Interface-Einheiten.",
	["The width the location keeps when it is fixed."] = "Die Breite, die der Ort beh\195\164lt, wenn sie fest ist.",
	["The window shrinks as soon as it needs less room. Off keeps its size until you close it."] = "Das Fenster schrumpft, sobald es weniger Platz braucht. Aus beh\195\164lt seine Gr\195\182\195\159e, bis Ihr es schlie\195\159t.",
	["The zoom slider's fill and the active buttons follow your class colour or your own colour."] = "Die F\195\188llung des Zoomreglers und die aktiven Kn\195\182pfe folgen Eurer Klassenfarbe oder Eurer eigenen Farbe.",
