	["Thick"] = "Dick",
	["Thick outline"] = "Dicker Umriss",
	["Thin"] = "D\195\188nn",
	["Thin gilt rails and plain pointed ends on frames, bars and nameplates, with small arrow caps beside the action bars."] = "Schmale vergoldete Leisten und schlichte spitze Enden an Rahmen, Leisten und Namensplaketten, mit kleinen Pfeilkappen neben den Aktionsleisten.",
	["Thin outline"] = "D\195\188nner Umriss",
	["This account string is not valid."] = "Diese Kontozeichenfolge ist ung\195\188ltig.",
