	["Tooltips use the font from Appearance. Turn off to pick a font for each kind of line."] = "Tooltips nutzen die Schrift aus Darstellung. Schaltet es aus, um f\195\188r jede Zeilenart eine Schrift zu w\195\164hlen.",
	["Top"] = "Oben",
	["Top centre"] = "Oben mittig",
	["Top docks to the slab in Medallions. Dock follows the action bars. Rail is the old readout."] = "Oben dockt in Medaillons am Sockel an. Andocken folgt den Aktionsleisten. Rand nutzt die alte Anzeige.",
	["Top left"] = "Oben links",
	["Top right"] = "Oben rechts",
	["Top to bottom"] = "Von oben nach unten",
	["Total"] = "Gesamt",
	["Track currencies on the backpack to see them here."] = "Verfolge W\195\164hrungen am Rucksack, um sie hier zu sehen.",
	["Tracked buff bars"] = "Leisten verfolgter St\195\164rkungszauber",
	["Tracked buff icons"] = "Symbole verfolgter St\195\164rkungszauber",
	["Tracked currencies"] = "Verfolgte W\195\164hrungen",
	["Tracked on the backpack"] = "Am Rucksack verfolgt",
	["Tracking"] = "Aufsp\195\188ren",
	["Tracking button"] = "Aufsp\195\188rknopf",
