	["Trainer"] = "Lehrer",
	["Travel"] = "Reisen",
	["Travel above you"] = "Weg \195\188ber Euch",
	["Travel on frames"] = "Weg auf Rahmen",
	["Travel with smooth map zoom, search and a straight-line route card showing distance and time."] = "Reist mit weichem Kartenzoom, Suche und einer Routenkarte f\195\188r die Luftlinie mit Entfernung und Zeit.",
	["Tray"] = "Leiste",
	["Tray card"] = "Leistenkarte",
	["Tray on the centre column"] = "Leiste auf der Mittelspalte",
	["Trims the top and bottom of each debuff into a wide tile."] = "Schneidet jede Schw\195\164chung oben und unten zu einer breiten Kachel zu.",
	["Try again"] = "Erneut versuchen",
	["Tune each action bar with its own tab for text, cooldowns, quality borders and show/hide rules."] = "Stellt jede Aktionsleiste in einem eigenen Reiter f\195\188r Text, Abklingzeiten, Qualit\195\164tsrahmen und Ein-/Ausblendregeln ein.",
	["Turn on the Cooldown Manager in %s to see the restyled cooldowns."] = "Schaltet den Abklingzeitmanager unter %s ein, um die neu gestalteten Abklingzeiten zu sehen.",
	["Turn this frame off to leave its unit without a KstyleUI frame."] = "Schaltet diesen Rahmen aus, um seiner Einheit keinen KstyleUI-Rahmen zu geben.",
	["Turns Blizzard's gold and white lines into KstyleUI's greys. Coloured lines stay."] = "Macht Blizzards goldene und wei\195\159e Zeilen zu KstyleUIs Graut\195\182nen. Farbige Zeilen bleiben.",
	["Turns the map so you always face up, and hides the N. Off leaves the game's own setting alone."] = "Dreht die Karte, sodass du immer nach oben blickst, und blendet das N aus. Aus l\195\164sst die Spieleinstellung.",
	["Turns these game plates on or off. The game's setting leaves them alone."] = "Schaltet diese Plaketten des Spiels an oder aus. Einstellung des Spiels l\195\164sst sie unver\195\164ndert.",
	["Turns this bar on or off."] = "Schaltet diese Leiste an oder aus.",
	["Turns this bar on or off. Beside the party frames it lowers the largest HUD size."] = "Schaltet diese Leiste an oder aus. Neben den Gruppenrahmen senkt sie die gr\195\182\195\159te HUD-Gr\195\182\195\159e.",
	["Turns this module on or off."] = "Schaltet dieses Modul an oder aus.",
	["Turns web addresses into links. Click one to copy it."] = "Macht Webadressen zu Links. Klickt einen an, um ihn zu kopieren.",
	["Two movable anchors; attach your own auras to KstyleUI_WeakAuras1 and KstyleUI_WeakAuras2."] = "Zwei verschiebbare Anker; befestigt Eure Auren an KstyleUI_WeakAuras1 und KstyleUI_WeakAuras2.",
	["Two rows on the slab"] = "Zwei Reihen auf der Platte",
	["Two-Hand"] = "Zweih\195\164ndig",
	["Type /kb to hover a button and press a key to bind it. Save for your account or this character, or Discard your changes."] = "Gebt /kb ein, zeigt auf eine Schaltfl\195\164che und dr\195\188ckt eine Taste zum Belegen. Speichert f\195\188r Euren Account oder diesen Charakter, oder verwerft die \195\132nderungen.",
	["Type /reload to reload the interface."] = "Gebt /reload ein, um die Oberfl\195\164che neu zu laden.",
	["Type icon"] = "Artsymbol",
	["Type icon size"] = "Gr\195\182\195\159e des Artsymbols",
	["Type set"] = "Schriftpaket",
	["Type slider values"] = "Reglerwerte eingeben",
	["Type the confirmation word when you delete a good item. You still click Yes."] = "Tr\195\164gt das Best\195\164tigungswort ein, wenn du einen guten Gegenstand l\195\182schst. Auf Ja klickst du selbst.",
	["Ultrawide arrangement"] = "Ultrawide-Anordnung",
	["Uncheck all"] = "Alle abw\195\164hlen",
	["Uncommon and better"] = "Ungew\195\182hnlich und besser",
	["Under the icon"] = "Unter dem Symbol",
	["Under the plate"] = "Unter der Plakette",
	["Under the points"] = "Unter den Punkten",
	["Underlines a debuff in gold once refreshing it keeps its full duration."] = "Unterstreicht eine Schw\195\164chung golden, sobald ein Auffrischen ihre volle Dauer erh\195\164lt.",
	["Undo"] = "R\195\188ckg\195\164ngig",
	["Undo the last change. Ctrl+Z."] = "Macht die letzte \195\132nderung r\195\188ckg\195\164ngig. Strg+Z.",
	["Unfriendly"] = "Unfreundlich",
	["Uninterruptible colour"] = "Farbe nicht unterbrechbarer Zauber",
	["Unit Frames"] = "Einheitenfenster",
	["Unit and group frame bars that show this power use this colour."] = "Einheiten- und Gruppenleisten mit dieser Ressource nutzen diese Farbe.",
	["Unit edge"] = "Einheitenkante",
	["Unit frames"] = "Einheitenfenster",
	["Unit frames, nameplates, raids, bags, tooltips, meter and skins."] = "Einheitenfenster, Namensplaketten, Schlachtz\195\188ge, Taschen, Tooltips, Schadensanzeige und Skins.",
	["Unit name font"] = "Einheitennamenschrift",
	["Unit tooltips"] = "Einheitentooltips",
	["Unit types"] = "Einheitenarten",
	["Units"] = "Einheiten",
	["Units after the value: 179 fps, 55% armour"] = "Einheiten nach dem Wert: 179 FPS, 55% R\195\188stung",
	["Unknown"] = "Unbekannt",
