	["Unspent talents alert"] = "Hinweis auf unverteilte Talente",
	["Untrack some in the Cooldown Manager and press Try again, or move them in Edit Mode."] = "Verfolgt im Abklingzeitmanager einige nicht mehr und w\195\164hlt Erneut versuchen, oder verschiebt sie im Bearbeitungsmodus.",
	["Up"] = "Oben",
	["Up, above the name"] = "Nach oben, \195\188ber dem Namen",
