	["Use KstyleUI's font"] = "KstyleUI-Schrift nutzen",
	["Use KstyleUI's quest card"] = "KstyleUIs Questkarte verwenden",
	["Use Questie's quest tracker"] = "Questies Questverfolgung verwenden",
	["Use Side"] = "Seite verwenden",
	["Use a full title band and smaller category headings. Off restores the previous headings."] = "Volles Titelband und kleinere Kategorien. Aus: bisherige \195\156berschriften.",
	["Use a profile per specialization"] = "Ein Profil je Spezialisierung",
	["Use a separate fill colour while you channel a spell."] = "Verwendet beim Kanalisieren eines Zaubers eine eigene F\195\188llfarbe.",
	["Use compact sans capitals for Medallions meter names. Off restores the original face."] = "Kompakte serifenlose Namen auf Medallions-Anzeigen. Aus stellt die alte Schrift wieder her.",
	["Use equipped gear or your best owned gear for the item level readout."] = "Nutzt die angelegte oder beste vorhandene Ausr\195\188stung f\195\188r die Gegenstandsstufe.",
	["Use readability setting"] = "Lesbarkeitseinstellung verwenden",
	["Use shared window sizes and spacing. Off restores previous layouts; reload to apply."] = "Einheitliche Fensterma\195\159e und Abst\195\164nde. Aus: bisherige Anordnung. Neu laden n\195\182tig.",
	["Use short or full numbers for damage and healing amounts."] = "Kurze oder vollst\195\164ndige Zahlen f\195\188r Schaden und Heilung verwenden.",
	["Use slimmer switches with a clearer On colour. Off restores the taller, dimmer switches."] = "Schmalere Schalter zeigen Ein deutlicher. Aus stellt die h\195\182heren, dunkleren Schalter wieder her.",
	["Use small muted capitals under the Medallions sockets. Off restores the original face."] = "Kleine dezente Gro\195\159buchstaben unter den Medallions-Feldern. Aus stellt die alte Schrift wieder her.",
	["Use the HUD's bar finish and placement. Turn off for the previous swing timer."] = "Balkenstil und Position des HUDs. Ausschalten f\195\188r den bisherigen Schwungtimer.",
	["Use the Medallions slab"] = "Medaillonplatte verwenden",
	["Use the game's smoothing for cast and channel progress."] = "Verwendet die Gl\195\164ttung des Spiels f\195\188r Zauber- und Kanalisierungsfortschritt.",
	["Use the minimap's local area name. Off shows the whole zone."] = "Verwendet den lokalen Gebietsnamen der Minikarte. Aus: gesamte Zone.",
	["Use the number face on a larger Medallions level badge. Off restores the original badge."] = "Ziffernschrift auf gr\195\182\195\159erem Medallions-Stufenabzeichen. Aus stellt das alte Abzeichen wieder her.",
	["Use the tray"] = "HUD-Rahmen verwenden",
	["Use these colours in every profile"] = "Diese Farben in jedem Profil nutzen",
	["Use type set"] = "Schriftpaket verwenden",
	["Use wrapping 11-unit notes in setup. Off restores the smaller, single-line module notes."] = "Zeigt umbrochene Hinweise mit Gr\195\182\195\159e 11. Aus stellt kleine einzeilige Modulhinweise wieder her.",
	["Use your class colour as you enter combat."] = "Nutzt Eure Klassenfarbe beim Betreten des Kampfes.",
	["Use your class colour as you leave combat."] = "Nutzt Eure Klassenfarbe beim Verlassen des Kampfes.",
	["Use your class colour for the cursor ring."] = "Nutzt Eure Klassenfarbe f\195\188r den Zeigerring.",
	["Use your class colour for the unspent talents alert."] = "Nutzt Eure Klassenfarbe f\195\188r den Talenthinweis.",
	["Use your class colour, or a colour you pick, for lines, fills and glows."] = "Nutzt Eure Klassenfarbe oder eine Farbe Eurer Wahl f\195\188r Linien, F\195\188llungen und Leuchten.",
	["Use your font for game text"] = "Eure Schriftart f\195\188r Spieltext",
	["Use your names font for names in the world"] = "Eure Namenschrift f\195\188r Namen in der Welt",
	["Use your number font for combat text"] = "Eure Zahlenschrift f\195\188r Kampftext",
	["Used"] = "Belegt",
	["Used / total"] = "Belegt / gesamt",
	["Uses 35 percent opacity and label tags on movers. Off restores the old solid plates."] = "Nutzt dunkle Verschiebeplatten mit 35 Prozent Deckkraft und Namen. Aus stellt die alten festen Platten her.",
	["Uses a dark metal rim around aura tiles in Medallions. Off restores the black rim."] = "Gibt Aurafeldern im Medaillonstil einen dunklen Metallrand. Aus nutzt den schwarzen Rand.",
	["Uses distinct role symbols on compact frames. Off restores the coloured pips."] = "Nutzt verschiedene Rollensymbole auf kompakten Rahmen. Aus stellt die farbigen Punkte wieder her.",
	["Uses the action slab's metal frame for cooldown and tracked buff icons in Medallions."] = "Nutzt den Metallrahmen der Aktionsleiste f\195\188r Abklingzeit- und St\195\164rkungssymbole bei Medaillons.",
	["Uses the number font for debuff timers and stacks. Turn off to use the plate font."] = "Verwendet die Zahlenschrift f\195\188r Dauer und Stapel von Schw\195\164chungen. Aus: Namensplakettenschrift.",
	["Uses the other element's height within this element's size limits."] = "\195\156bernimmt die H\195\182he des anderen Elements innerhalb der eigenen Gr\195\182\195\159engrenzen.",
	["Uses the other element's width within this element's size limits."] = "Verwendet die Breite des anderen Elements innerhalb der Gr\195\182\195\159enbegrenzungen dieses Elements.",
	["Uses the role font unless you choose a font for this text."] = "Nutzt die Rollenschrift, solange keine eigene Schrift f\195\188r diesen Text gew\195\164hlt ist.",
	["Uses the same bare seconds and minute labels as action buttons."] = "Nutzt dieselben Sekunden ohne Zusatz und Minutenangaben wie Aktionsschaltfl\195\164chen.",
	["Uses the skin's font for tracker text. Turning it off needs a reload."] = "Nutzt die Schrift des Skins f\195\188r den Verfolgungstext. Ausschalten braucht ein Neuladen.",
	["Usual colour while you can interrupt"] = "\195\156bliche Farbe, solange du unterbrechen kannst",
