	["Warn below"] = "Warnen unter",
	["Warn out of combat when worn gear wears down."] = "Warnt au\195\159erhalb des Kampfes, wenn getragene Ausr\195\188stung verschlei\195\159t.",
	["Warn under"] = "Warnen unter",
	["Warn when any worn item falls below this durability, in percent."] = "Warnt, wenn ein getragener Gegenstand unter diese Haltbarkeit f\195\164llt, in Prozent.",
	["Warning colour"] = "Warnfarbe",
	["Warning height"] = "Warnungsh\195\182he",
	["Warrior"] = "Krieger",
