	["WeakAuras anchors"] = "WeakAuras-Anker",
	["Weapon enchantments"] = "Waffenverzauberungen",
	["Welcome"] = "Willkommen",
	["Welcome text, the French and German Options footer, the 1080p data bar and colour-vision health bars read right."] = "Willkommenstext, die franz\195\182sische und deutsche Fu\195\159zeile der Optionen, die Datenleiste bei 1080p und die Gesundheitsleisten f\195\188r Farbsehschw\195\164chen werden richtig angezeigt.",
	["Welcome to KstyleUI"] = "Willkommen bei KstyleUI",
	["What happens when you learn a higher rank of a spell on your bars."] = "Was passiert, wenn Ihr einen h\195\182heren Rang eines Zaubers auf Euren Leisten lernt.",
	["What happens when you learn an active spell that is not on your bars."] = "Was passiert, wenn du einen aktiven Zauber erlernst, der noch nicht auf deinen Leisten liegt.",
	["What the bag window shows each time it opens."] = "Was das Taschenfenster bei jedem \195\150ffnen zeigt.",
	["What the health text shows."] = "Was der Gesundheitstext zeigt.",
	["What the text on the bar says."] = "Was der Text auf der Leiste sagt.",
	["What the window measures. Click its title to switch between damage and healing in game."] = "Was das Fenster misst. Klickt im Spiel auf seinen Titel, um zwischen Schaden und Heilung zu wechseln.",
	["What this indicator shows; slots sharing a place sit side by side."] = "Was dieser Anzeiger zeigt; Pl\195\164tze am selben Ort sitzen nebeneinander.",
	["What your bags do when this window opens and closes. Closing only closes bags it opened."] = "Was deine Taschen tun, wenn dieses Fenster auf- und zugeht. Es schlie\195\159t nur Taschen, die es ge\195\182ffnet hat.",
	["What's new"] = "Neuigkeiten",
	["Wheel between maps"] = "Karten mit dem Mausrad wechseln",
	["Wheel out past a map's edge to its parent, or in over a zone to open it."] = "Am Rand herauszoomen \195\182ffnet die \195\188bergeordnete Karte, hineinzoomen \195\188ber einer Zone \195\182ffnet sie.",
	["When a condition matches"] = "Wenn eine Bedingung zutrifft",
	["When all layouts are full, choose one to replace. Off keeps the previous full-list message."] = "W\195\164hlt bei voller Layoutliste eines zum Ersetzen. Aus beh\195\164lt den bisherigen Hinweis zur vollen Liste.",
	["When hovering a button shows its tooltip."] = "Wann das \195\156berfahren eines Knopfs seinen Tooltip zeigt.",
	["When hovering a unit frame shows the unit's tooltip."] = "Wann das \195\156berfahren eines Einheitenrahmens den Tooltip der Einheit zeigt.",
	["When hovering an icon shows its tooltip."] = "Wann das Ber\195\188hren eines Symbols seinen Tooltip zeigt.",
	["When solo only"] = "Nur allein",
	["When the colours are close, draws power in steel with a thin line of its original colour."] = "Bei \195\164hnlichen Farben wird die Ressource in Stahlgrau mit einer d\195\188nnen Linie ihrer urspr\195\188nglichen Farbe dargestellt.",
	["When the crosshair shows."] = "Wann das Fadenkreuz erscheint.",
	["When the cursor ring shows."] = "Wann der Zeigerring erscheint.",
	["When the element shows."] = "Wann das Element erscheint.",
	["When the game auto loots, take every item the moment the window opens."] = "Wenn das Spiel automatisch pl\195\188ndert, wird alles sofort beim \195\150ffnen genommen.",
	["When the member's tooltip shows as you point at a frame."] = "Wann der Tooltip des Mitglieds erscheint, wenn Ihr auf einen Rahmen zeigt.",
	["When these hide, the icons after them move up, even with Close gaps off."] = "Wenn diese verschwinden, r\195\188cken die folgenden Symbole nach, auch wenn L\195\188cken schlie\195\159en aus ist.",
	["Where a short row starts."] = "Wo eine kurze Reihe beginnt.",
	["Where each debuff's stacks sit."] = "Wo die Stapel jeder Schw\195\164chung sitzen.",
	["Where each debuff's time left sits."] = "Wo die Restzeit jeder Schw\195\164chung sitzt.",
	["Where each value sits in its cell. One line sizes each readout to its text."] = "Wo jeder Wert in seiner Zelle steht. In einer Zeile passt sich jede Anzeige ihrem Text an.",
	["Where it sits inside the map's edge."] = "Wo es innen am Kartenrand sitzt.",
	["Where numbers show"] = "Wo Zahlen erscheinen",
	["Where on the frame the indicator sits."] = "Wo auf dem Rahmen der Anzeiger sitzt.",
	["Where on the health bar the combat icon sits."] = "Wo auf dem Gesundheitsbalken das Kampfsymbol sitzt.",
	["Where on the health bar the raid marker sits; Automatic keeps today's place."] = "Wo auf dem Gesundheitsbalken die Schlachtzugsmarkierung sitzt; Automatisch beh\195\164lt den bisherigen Platz.",
	["Where on the health bar the ready check, resurrection, summon and AFK icons sit."] = "Wo auf dem Gesundheitsbalken die Symbole f\195\188r Bereitschaftscheck, Wiederbelebung, Beschw\195\182rung und AFK sitzen.",
	["Where on the icon the stack count sits: in a corner, on an edge or in the centre."] = "Wo die Stapelanzahl auf dem Symbol steht: in einer Ecke, an einem Rand oder in der Mitte.",
	["Where the bar's colour comes from."] = "Woher die Farbe der Leiste kommt.",
	["Where the countdown colour comes from."] = "Woher die Countdown-Farbe stammt.",
	["Where the countdown sits on each icon."] = "Wo der Countdown auf jedem Symbol sitzt.",
	["Where the debuff icons sit on or beside the frame."] = "Wo die Schw\195\164chungssymbole auf oder neben dem Rahmen sitzen.",
	["Where the glow colour comes from."] = "Woher die Leuchtfarbe stammt.",
	["Where the swipe tint comes from."] = "Woher die Ablauff\195\164rbung stammt.",
	["Where the text sits around the bar."] = "Wo der Text bei der Leiste sitzt.",
	["Where the threat percent sits inside the health bar."] = "Wo der Bedrohungsanteil im Gesundheitsbalken steht.",
	["Where the time sits in its frame."] = "Wo die Zeit in ihrem Rahmen steht.",
	["Where the tooltip opens beside the mouse."] = "Wo der Tooltip neben der Maus erscheint.",
	["Where this text sits on the frame."] = "Die Position dieses Textes am Rahmen.",
	["Wherever KstyleUI shows this class colour; the accent keeps its own setting."] = "\195\156berall, wo KstyleUI diese Klassenfarbe zeigt; der Akzent beh\195\164lt seine eigene Einstellung.",
	["Whether buttons fill each row or each column first."] = "Ob Kn\195\182pfe zuerst jede Reihe oder jede Spalte f\195\188llen.",
	["Whether extra rows go below or above the first."] = "Ob zus\195\164tzliche Reihen unter oder \195\188ber der ersten liegen.",
	["Whether new bars stack upward or downward."] = "Ob neue Leisten nach oben oder unten stapeln.",
	["Whether rows of debuffs stack upward above the name or downward under the cast bar."] = "Ob Reihen von Schw\195\164chungszaubern nach oben \195\188ber den Namen oder nach unten unter den Zauberbalken stapeln.",
	["Whether the buttons start at the top or the bottom of the column."] = "Ob die Kn\195\182pfe oben oder unten in der Spalte beginnen.",
	["Whether the fill runs across or up the bar."] = "Ob die F\195\188llung quer oder nach oben durch die Leiste l\195\164uft.",
	["Which auras"] = "Welche Auren",
	["Which corner of each aura icon shows its stack count."] = "In welcher Ecke jedes Aurensymbols die Stapelzahl steht.",
	["Which debuffs"] = "Welche Schw\195\164chungszauber",
	["Which debuffs take this place in the row; a repeat counts once."] = "Welche Schw\195\164chungszauber diesen Platz in der Reihe einnehmen; eine Wiederholung z\195\164hlt einmal.",
	["Which edge of the health bar the shield line runs along."] = "An welchem Rand des Gesundheitsbalkens die Schildlinie verl\195\164uft.",
	["Which edge of the map the small buttons line."] = "An welchem Kartenrand die kleinen Kn\195\182pfe stehen.",
	["Which end skinned bars fill from."] = "Von welchem Ende gestaltete Leisten sich f\195\188llen.",
	["Which layer the element draws in, from back to front."] = "Auf welcher Ebene das Element gezeichnet wird, von hinten nach vorn.",
	["Which side of the bars the portrait sits on."] = "Auf welcher Seite der Leisten das Portr\195\164t sitzt.",
	["Which side of the frame the auras sit on."] = "Auf welcher Seite des Rahmens die Auren sitzen.",
	["Which side of the other element this one sits on."] = "Auf welcher Seite des anderen Elements dieses sitzt.",
	["Which slot count the bag readout shows."] = "Welche Platzzahl die Taschenanzeige zeigt.",
	["Which volume the audio readout shows."] = "Welche Lautst\195\164rke die Audioanzeige zeigt.",
	["Which way a new row of debuff icons goes."] = "In welche Richtung eine neue Reihe Schw\195\164chungssymbole geht.",
	["Which way a row of debuffs grows."] = "In welche Richtung eine Reihe Schw\195\164chungszauber w\195\164chst.",
	["Which way a shield line on the left or right edge grows."] = "In welche Richtung eine Schildlinie am linken oder rechten Rand w\195\164chst.",
	["Which way button tooltips open. Tooltips > Keep minimap clear places them while it is on."] = "In welche Richtung Tasten-Tooltips \195\182ffnen. Tooltips > Minikarte freihalten platziert sie, wenn aktiv.",
